describe('wxFormat', () => {
  it.each(GLIBC)('%s of %j is what glibc prints', (fmt, args, want) => {
    expect(wxFormat(fmt, ...args)).toBe(want);
  });

  it('keeps a translated message right when the translation reorders its arguments', () => {
    // A translator's msgstr may name the arguments by position; the call is unchanged.
    expect(wxFormat('Pin %s of %s', '3', 'U1')).toBe('Pin 3 of U1');
    expect(wxFormat('%2$s 的引脚 %1$s', '3', 'U1')).toBe('U1 的引脚 3');
  });

  it('prints nothing for an argument that is not there', () => {
    expect(wxFormat('%s and %s', 'one')).toBe('one and ');
  });
});
